# Conductor CHECKLIST JUDGE for C-6 P2 pass 3 (rubric law: one boolean per owner item, R-C6-9/10/11) + geometry axis + hidden mirrored control.
# usage: mk_p2_judge2.py <bid> <dirs csv incl. S> <ctrl_src dir> <ctrl_claim dir> [D=relpath ...]  (defaults: S = master 512; others runs/C-6/artifacts/N6-turn-<d>/n6_<d>.png)
import json, pathlib, sys
from PIL import Image, ImageOps
B = pathlib.Path('/Users/admin/Games/reincarnated-collaboration/astra_test_01/burst'); A = B/'runs/C-6/artifacts'
T = json.load(open(B/'runs/C-6/n5_facing_table.json'))['table']
T['S'] = "facing the camera (S): the blade above and screen-LEFT of his head (his right), the horn on his LEFT shoulder (screen-right), the tome at his left hip (screen-right), both hands on the haft. This is the master itself; judge its head and camera like any other candidate."
bid = sys.argv[1]; dirs = sys.argv[2].split(','); ctrl_src = sys.argv[3]; ctrl_claim = sys.argv[4]; srcs = dict(a.split('=') for a in sys.argv[5:]) if len(sys.argv) > 5 else {}
def path(d): return A/srcs.get(d, 'N3-final-cam-01/necro_master_S_512.png' if d == 'S' else f'N6-turn-{d}/n6_{d}.png')
(A/'N6-control').mkdir(parents=True, exist_ok=True)
cp = A/'N6-control'/f'{bid}_control_mirror.png'; ImageOps.mirror(Image.open(path(ctrl_src))).save(cp)
cands = [(d, path(d)) for d in dirs]; cands.insert(len(cands)//2, (ctrl_claim, cp))
refs = [{"path": str(A/'N1-refs/necro_master_final_app.png'), "role": "IMAGE 1 — the OWNER'S MASTER at full resolution (frontal-low camera; identity source of truth)"},
        {"path": str(A/'N3-final-cam-01/necro_master_S_512.png'), "role": "IMAGE 2 — the master at the SCENE CAMERA (53° down) and cell scale: the camera/scale reference"}]
lines = []
for i, (d, p) in enumerate(cands, 3):
    refs.append({"path": str(p), "role": f"candidate, claimed direction {d}"}); lines.append(f"Image {i} claims {d}. EXPECTED for {d}: {T[d]}")
text = (f"JUDGE BURST {bid} — the Necromancer's turnaround, OWNER-CHECKLIST pass (Run C-6 P2): every item below was a defect the owner found in the previous pass; verify each by looking, not by claim. task_id \"{bid}\". You are a separate instance: you have not seen any prompt, receipt, check or prior judgment, and must not look for one.\n\n"
 "Image 1 is the owner's master at full resolution — read the INVARIANTS from it: PALE ICE-BLUE eyes; a ROUND PLAIN SILVER belt disc with a small leaf-like sigil (NO skull); a POLISHED SILVER-STEEL ribcage relief on a black cuirass (metal, not bone); ONE bone horn on HIS LEFT shoulder, nothing on the right; a small dark-leather TOME at his LEFT hip with SILVER CORNER CAPS and a short RED RIBBON marker, no other emblem; a war scythe in EXACTLY TWO gauntleted hands; NO skull anywhere on him. Image 2 is the same master at the scene camera: an elevated view looking DOWN ~53° (crown and shoulder tops seen from above, feet foreshortened) at cell scale — the camera and scale every candidate must match.\n"
 "GEOMETRY RULE (sides): turned toward screen-RIGHT he shows his RIGHT side — the BLADE over the near shoulder; toward screen-LEFT his LEFT side — HORN + TOME near, blade behind the far shoulder; back views: blade SCREEN-RIGHT of the head, horn SCREEN-LEFT. Wrong sides for the claim = MIRRORED. Judge each candidate independently; do not assume any is a control or correct.\n\n"
 + "\n".join(lines) +
 "\n\nFor EACH candidate write the CHECKLIST as booleans, each with one line of visible evidence:\n"
 "eyes_blue (pale blue irises visible; if the face is hidden write null) · head_level (HARD: the face is NOT angled toward the ground at all — chin level or fractionally raised, eyes on the horizon; any downward bow = false; if the face is hidden judge from the skull/hair angle) · head_aligned (not tilted sideways, not turned against the body) · no_skull_buckle · no_skull_shoulder · no_skull_book · ribcage_steel (silver metal, not bone/ivory; null if the back is shown) · tome_master_ornament (corner caps + red ribbon, nothing else; null if hidden) · hands_exactly_two (exactly two gauntlets, both on the haft, none emerging from the torso or floating) · hands_in_front (back views: no arms bent behind the back; null for front views) · camera_matches (crown/shoulder tops seen from above and feet foreshortened as in Image 2 — not eye-level, not shallower) · scale_matches (sole-to-crown height the same fraction of the canvas as Image 2, ±10 %) · mirrored (sides swapped for the claim) · seen_facing.\n"
 "Then axes 1–5 (integers, one-line reasons): 1 register · 2 identity (count the checklist falses) · 3 light (key screen upper-left) · 4 equipment geometry vs EXPECTED (all correct = 5; each error −1; mirrored = 1) · 5 direction read at 64 px.\n"
 "Write out/judgment.json: {\"candidates\":[{\"image\":n,\"claimed\":\"…\",\"seen_facing\":\"…\",\"checklist\":{\"eyes_blue\":bool|null,\"head_level\":bool,\"head_aligned\":bool,\"no_skull_buckle\":bool,\"no_skull_shoulder\":bool,\"no_skull_book\":bool,\"ribcage_steel\":bool|null,\"tome_master_ornament\":bool|null,\"hands_exactly_two\":bool,\"hands_in_front\":bool|null,\"camera_matches\":bool,\"scale_matches\":bool},\"evidence\":{\"head_level\":\"…\",…},\"mirrored\":bool,\"axes\":{\"1\":n,…},\"reasons\":{\"4\":\"…\",…}}, …]}. No image_gen. No code. No web. No files outside out/. calls_used must be 0.\n"
 f"RETURN: receipt task_id \"{bid}\"; images []; files [out/judgment.json + sha256]; status DELIVERED / DELIVERED_WITH_CONCERNS; concerns for anything you could not assess. Never PASS/FAIL — booleans and scores only.")
task = {"text": text, "references": refs, "image_cap": 0, "minutes_cap": 15, "tool_call_cap": 20, "outputs": ["out/judgment.json"], "effort": "high", "add_dirs": [], "experiment": "C6-P2"}
json.dump(task, open(B/f'briefs/C-6/{bid}.task.json', 'w'), indent=1, ensure_ascii=False)
print(bid, 'control = mirror of', ctrl_src, 'claimed', ctrl_claim, 'at image', [i for i,(d,p) in enumerate(cands,3) if p==cp][0], '| chars', len(text))
